INSERT INTO entities (id, name, type, bio, url) VALUES ('tt-perry', 'TT Perry', 'person', 'Dr. T.T. Perry (TTP, PhD) is a researcher, academic, and nonbinary intactivist who offers critical perspectives on genital autonomy. An active observer and ally in landmark legal challenges, including Hadachek v. Oregon, working closely with organizations like the Genital Autonomy Collective and GALDEF.', 'https://ttpphd.com/'), ('genital-autonomy-league', 'Genital Autonomy League', 'organization', 'The Genital Autonomy League (often associated with the Genital Autonomy Collective and GALDEF) is a coalition dedicated to protecting the bodily integrity and equal protection rights of all children, actively supporting legal challenges like Hadachek v. Oregon.', '') ON CONFLICT(id) DO UPDATE SET bio = excluded.bio, url = excluded.url;
